alter table public.conversation_introductions drop constraint if exists introduction_icebreaker_length;
alter table public.conversation_introductions add constraint introduction_icebreaker_length check (icebreaker = '' or char_length(icebreaker) between 50 and 500);
create or replace function public.submit_introduction(other_user uuid, introduction text) returns uuid language plpgsql security definer set search_path = public as $$ declare intro_id uuid; me uuid := auth.uid(); recipient_accepts boolean; recipient_scope text; body text := trim(coalesce(introduction, '')); body_hash text := md5(regexp_replace(lower(body), '\s+', ' ', 'g')); begin perform public.expire_introductions(); if me is null or me = other_user then raise exception 'Invalid participant'; end if; if char_length(body) < 50 or char_length(body) > 500 or body !~ '^[[:alnum:]].*[[:alnum:]]$' or (select count(*) from regexp_split_to_table(body, '\s+') as words) < 8 then raise exception 'Icebreaker must be 50 to 500 characters and at least 8 words'; end if; select accepting_new_conversations, introduction_scope into recipient_accepts, recipient_scope from public.profiles where id = other_user; if recipient_accepts is null or not recipient_accepts or recipient_scope = 'nobody' then raise exception 'This user is not accepting new conversations'; end if; if exists (select 1 from public.profile_blocks where (blocker_id = me and blocked_id = other_user) or (blocker_id = other_user and blocked_id = me)) then raise exception 'Conversation unavailable'; end if; if exists (select 1 from public.conversation_participants cp join public.conversation_participants cp2 on cp2.conversation_id = cp.conversation_id where cp.user_id = me and cp2.user_id = other_user) then raise exception 'Conversation already exists'; end if; if exists (select 1 from public.conversation_introductions where sender_id = me and recipient_id = other_user and status = 'pending') then raise exception 'Introduction already pending'; end if; if (select count(*) from public.conversation_introductions where sender_id = me and created_at > now() - interval '1 hour') >= 10 then raise exception 'Introduction rate limit reached'; end if; if (select count(distinct recipient_id) from public.conversation_introductions where sender_id = me and normalized_hash = body_hash and created_at > now() - interval '24 hours') >= 3 then raise exception 'Repeated introduction blocked'; end if; insert into public.conversation_introductions (sender_id, recipient_id, body, normalized_hash, icebreaker, expires_at, status) values (me, other_user, body, body_hash, body, now() + interval '7 days', 'pending') returning id into intro_id; return intro_id; end; $$;
